package com.dreamcore.workspace.departure;
import java.io.*;import java.security.*;import java.util.*;import java.util.zip.*;import org.springframework.boot.autoconfigure.condition.*;import org.springframework.scheduling.annotation.*;import org.springframework.stereotype.Component;import tools.jackson.databind.json.JsonMapper;import com.dreamcore.workspace.identity.IdentityException;
@Component @EnableScheduling @ConditionalOnWebApplication(type=ConditionalOnWebApplication.Type.SERVLET)
public class DepartureArchiveWorker {
 private final DepartureArchiveService service;private final DepartureArchiveSources sources;private final JsonMapper json=new JsonMapper();private final boolean enabled;
 public DepartureArchiveWorker(DepartureArchiveService service,DepartureArchiveSources sources,@org.springframework.beans.factory.annotation.Value("${dreamcore.departure.archive-worker-enabled:true}")boolean enabled){this.service=service;this.sources=sources;this.enabled=enabled;}
 @Scheduled(fixedDelayString="${dreamcore.departure.archive-poll-ms:3000}",initialDelayString="${dreamcore.departure.archive-initial-delay-ms:30000}")public void tick(){if(enabled)runOnce();}
 public void runOnce(){service.expireDue();for(UUID id:service.pendingCleanup())try{service.cleanup(id);}catch(Exception e){service.cleanupFailed(id);}var job=service.claim();if(job!=null)build(job);}
 public void build(DepartureArchiveService.Job job){try{var sink=new Sink(job);try(var zip=new ZipOutputStream(sink)){for(long ordinal:job.ordinals()){var selection=service.selection(job,ordinal);DepartureArchiveSources.File file;try{file=sources.export(job.actor(),job.tenant(),job.execution(),job.workspace(),selection);}catch(IdentityException e){service.item(job,ordinal,null,null,e.status==413?e.code:"DEPARTURE_EXPORT_ITEM_UNAVAILABLE");continue;}catch(Exception e){service.item(job,ordinal,null,null,"DEPARTURE_EXPORT_ITEM_FAILED");continue;}String safe=file.filename().replaceAll("[\\\\/\\p{Cntrl}]","_");if(safe.length()>150)safe=safe.substring(0,150);String path=String.format("%06d-",ordinal)+safe;zip.putNextEntry(new ZipEntry(path));zip.write(file.bytes());zip.closeEntry();service.item(job,ordinal,path,file.sha256(),null);}
    var stamp=service.stamp(job);var items=service.manifest(job);long included=items.stream().filter(i->i.state().equals("INCLUDED")).count();var manifest=new LinkedHashMap<String,Object>();manifest.put("schemaVersion",1);manifest.put("executionId",job.execution());manifest.put("workspaceId",job.workspace());manifest.put("setId",job.setId());manifest.put("partId",job.partId());manifest.put("generatedAt",stamp.generatedAt());manifest.put("expiresAt",stamp.expiresAt());manifest.put("completePart",included==items.size());manifest.put("fullTenantMigration",false);manifest.put("included",included);manifest.put("items",items);manifest.put("scopeNotes",List.of("此分包仅覆盖清单中的确切版本，不代表所有分包已生成或全企业迁出完成","私人会话、私人文稿、原始反馈、权限配置、凭据及平台数据不包含","独立经验不隐式附带原会话或受限来源正文"));zip.putNextEntry(new ZipEntry("_exit-manifest.json"));zip.write(json.writeValueAsBytes(manifest));zip.closeEntry();zip.finish();sink.finish();service.finish(job,stamp,sink.bytes(),sink.hash());}}
   catch(Exception e){service.fail(job,e instanceof IdentityException i?i.code:"DEPARTURE_EXPORT_GENERATION_FAILED");}
 }
 private final class Sink extends OutputStream{private final DepartureArchiveService.Job job;private final byte[] buffer=new byte[65536];private final MessageDigest digest;private int length,ordinal;private long bytes;private boolean finished;Sink(DepartureArchiveService.Job job){this.job=job;try{digest=MessageDigest.getInstance("SHA-256");}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}@Override public void write(int b){write(new byte[]{(byte)b},0,1);}@Override public void write(byte[] b,int offset,int count){if(finished)throw new IllegalStateException("Archive already finalized");while(count>0){int n=Math.min(count,buffer.length-length);System.arraycopy(b,offset,buffer,length,n);length+=n;offset+=n;count-=n;if(length==buffer.length)flushBlock();}}private void flushBlock(){if(length==0)return;bytes+=length;if(bytes>DepartureArchiveService.MAX_ARCHIVE)throw new IdentityException(413,"DEPARTURE_EXPORT_ARCHIVE_LIMIT");byte[] data=Arrays.copyOf(buffer,length);digest.update(data);service.chunk(job,ordinal++,data);length=0;}void finish(){flushBlock();finished=true;}long bytes(){return bytes;}String hash(){if(!finished)throw new IllegalStateException("Archive is incomplete");return HexFormat.of().formatHex(digest.digest());}}
}
